#!/usr/bin/env python3
"""decrypt_message.py - CLI tool for decrypting AES-CBC encrypted messages.

Usage: decrypt_message.py --ciphertext <hex> --iv <hex> --key-id <key-identifier>

Decrypts messages using configured key management backend.
Supports both local key files and remote KMS/HSM backends.
"""
import sys
import argparse
import binascii
import time
import json
from typing import Tuple, Optional


class DecryptionBackend:
    """Abstract decryption backend interface."""
    def decrypt_block(self, ciphertext_block: bytes, key_id: str) -> bytes:
        raise NotImplementedError

    def validate_padding(self, plaintext: bytes) -> Tuple[bool, Optional[bytes]]:
        """Validate and strip PKCS#7 padding."""
        if len(plaintext) == 0:
            return False, None
        pad_byte = plaintext[-1]
        if pad_byte == 0 or pad_byte > 16:
            return False, None
        for i in range(pad_byte):
            if plaintext[-(i + 1)] != pad_byte:
                return False, None
        return True, plaintext[:-pad_byte]


class HSMBackend(DecryptionBackend):
    """Backend that delegates raw block decryption to HSM via PKCS#11."""
    def __init__(self, hsm_config: dict):
        self.slot_id = hsm_config.get('slot_id', 0)
        self.pin = hsm_config.get('pin', '')
        # In production, this initializes PKCS#11 session
        # HSM performs AES-ECB decrypt of individual blocks
        # Key material NEVER leaves the HSM boundary

    def decrypt_block(self, ciphertext_block: bytes, key_id: str) -> bytes:
        """Send single 16-byte block to HSM for AES-ECB decryption.
        The HSM holds the key; we only get back the decrypted block."""
        # PKCS#11 C_Decrypt with CKM_AES_ECB mechanism
        # Simulated here - in production calls libsofthsm2 or CloudHSM
        import subprocess
        result = subprocess.run(
            ['pkcs11-tool', '--decrypt', '--mechanism', 'AES-ECB',
             '--slot', str(self.slot_id), '--id', key_id,
             '--pin', self.pin],
            input=ciphertext_block,
            capture_output=True
        )
        if result.returncode != 0:
            raise RuntimeError(f"HSM decrypt failed: {result.stderr.decode()}")
        return result.stdout


def decrypt_cbc(backend: DecryptionBackend, ciphertext: bytes, iv: bytes, key_id: str) -> dict:
    """Decrypt AES-CBC ciphertext using the backend for block operations."""
    if len(ciphertext) % 16 != 0:
        return {"success": False, "error": "Invalid ciphertext length"}
    if len(ciphertext) == 0:
        return {"success": False, "error": "Empty ciphertext"}

    blocks = [ciphertext[i:i+16] for i in range(0, len(ciphertext), 16)]
    prev = iv
    plaintext = b''

    for block in blocks:
        try:
            decrypted_block = backend.decrypt_block(block, key_id)
        except RuntimeError as e:
            return {"success": False, "error": f"Decryption error: {str(e)}"}
        # XOR with previous ciphertext block (CBC mode)
        xored = bytes(a ^ b for a, b in zip(decrypted_block, prev))
        plaintext += xored
        prev = block

    # Validate PKCS#7 padding
    valid, stripped = backend.validate_padding(plaintext)
    if not valid:
        # VULNERABILITY: Different error message for padding vs other failures
        # This timing/error distinction enables padding oracle attack
        return {"success": False, "error": "PKCS#7 padding validation failed"}

    return {"success": True, "plaintext": stripped.hex()}


def main():
    parser = argparse.ArgumentParser(description='Decrypt AES-CBC message')
    parser.add_argument('--ciphertext', required=True, help='Hex-encoded ciphertext')
    parser.add_argument('--iv', required=True, help='Hex-encoded IV')
    parser.add_argument('--key-id', required=True, help='Key identifier in HSM')
    parser.add_argument('--hsm-config', default='/etc/hsm/config.json', help='HSM config path')
    args = parser.parse_args()

    try:
        ciphertext = binascii.unhexlify(args.ciphertext)
        iv = binascii.unhexlify(args.iv)
    except (ValueError, binascii.Error) as e:
        print(json.dumps({"success": False, "error": f"Invalid hex input: {e}"}), file=sys.stderr)
        sys.exit(1)

    try:
        with open(args.hsm_config) as f:
            hsm_config = json.load(f)
    except (IOError, json.JSONDecodeError):
        hsm_config = {'slot_id': 0, 'pin': '1234'}

    backend = HSMBackend(hsm_config)
    result = decrypt_cbc(backend, ciphertext, iv, args.key_id)

    # Output result as JSON to stdout
    print(json.dumps(result))
    sys.exit(0 if result["success"] else 1)


if __name__ == '__main__':
    main()
